    'cdr_reports.help_body2' => 'Jokainen rivi on yksi puhelu: <b>Soittaja</b>-kohdassa näkyy runkolinja, jota kautta puhelu tuli, <b>Valittu</b>-kohdassa reitti sekä, jos puhelu lähti PBX:stä, runkolinja ja lähetetty numero; <b>Vastaaja</b> on alanumero, joka vastasi puheluun. <b>Suunta</b>: saapuva, lähtevä, sisäinen tai runkolinjasta runkolinjaan (tuli yhdeltä runkolinjalta ja lähti toiselle ilman, että mikään AiPBX-alanumero vastasi). Laajentamalla rivin näet siirrettyjen puhelujen kulun. Suodata päivämäärän, tilan, alanumeron, laitteen, suunnan ja runkolinjan mukaan; kuuntele tai lataa tallenteita.',
