    'asterisk_settings.rtp_section_title' => 'RTP (media) -asetukset',
    'asterisk_settings.rtp_help_body' => 'Määrittää, mitä porttialuetta ääni (RTP) käyttää ja hylkääkö Asterisk odottamattomasta lähteestä saapuvan äänen. Tämä tiedosto (<code>/etc/asterisk/rtp.conf</code>) luodaan nyt paneelista; palvelimella tehdyt käsin tehdyt muutokset menetetään seuraavassa ”Ota käyttöön” -toiminnossa.',
    'asterisk_settings.field_rtp_start' => 'RTP:n alkuportti',
    'asterisk_settings.rtp_start_help' => 'Äänivirroille varatun porttialueen alku. Jokainen samanaikainen puhelu käyttää portteja tältä alueelta.',
    'asterisk_settings.field_rtp_end' => 'RTP:n loppuportti',
    'asterisk_settings.rtp_end_help' => 'Alueen loppu. coturn (TURN-välitys) käyttää portteja 13479-14999 — päällekkäisyys rikkoo WebRTC-äänen, ja se hylätään tallennettaessa.',
    'asterisk_settings.field_rtp_strict' => 'Tiukka RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Kun käytössä, Asterisk hylkää äänettömästi kaiken äänen, joka saapuu muualta kuin opitusta etäosoitteesta/-portista (hyökkäyssuojaus). Jos vastapään PBX lähettää mediaa odottamattomasta portista, seurauksena on hiljainen ”ei ääntä” -vika ilman lokimerkintää — asetuksen voi kytkeä tilapäisesti pois vianmääritystä varten.',
    'asterisk_settings.rtp_strict_yes' => 'Käytössä (suositeltu)',
    'asterisk_settings.rtp_strict_no' => 'Ei käytössä (vianmääritystä varten)',
    'asterisk_settings.rtp_restart_warning' => 'Tiukka RTP -asetus tulee voimaan ”Ota käyttöön” -toiminnolla. PORTTIALUEEN muutos vaatii kuitenkin Asteriskin täydellisen uudelleenkäynnistyksen — porttivaranto varataan kerran moduulin latautuessa.',
    'asterisk_settings.udptl_section_title' => 'T.38 UDPTL (faksimedia) -asetukset',
    'asterisk_settings.udptl_help_body' => 'Määrittää UDP-porttialueet ja virheenkorjauksen (FEC / tarkistussumma) parametrit T.38-faksipaketeille (UDPTL). Tätä tiedostoa (<code>/etc/asterisk/udptl.conf</code>) hallitaan dynaamisesti.',
    'asterisk_settings.field_udptl_start' => 'UDPTL:n alkuportti',
