    'sound_packs.help_title' => 'Asteriskin äänipaketit',
    'sound_packs.help_body' => 'Asteriskin viralliset järjestelmäkehotteet ja pitomusiikki ladataan ja asennetaan osoitteesta <code>downloads.asterisk.org</code>. Kukin paketti on yksi kieli yhdessä muodossa; Asterisk toistaa puhelun koodekkia vastaavan muodon ja muuntaa muuten (g722 G.722:lle, ulaw/alaw operaattoreille).<br>- <strong>Core:</strong> järjestelmäkehotteet, numerot, puheposti. <strong>Extra:</strong> lisäkehotteet; saman kielen core-paketti on asennettava ensin.<br>- <strong>Pitomusiikki (opsound):</strong> asennetaan hakemistoon <code>/var/lib/asterisk/moh/opsound</code>; toistoa varten luodaan Pitomusiikki-välilehdellä MOH-luokka nimeltä <strong>opsound</strong>.<br>- <strong>Türkçe (AiPBX):</strong> AiPBX:n omat turkinkieliset kehotteet (GitHub-julkaisu, SHA256-tarkistettu); oletuskieli on turkki, joten niiden poistaminen mykistää järjestelmäkehotteet. Poisto poistaa vain paketin asentamat tiedostot.',
