    'system_update.page_title' => 'Järjestelmäpäivitys',
    'system_update.help_title' => 'Miten päivitys toimii?',
    'system_update.help_body' => 'Päivitys varmuuskopioi ensin tietokannan, asetukset ja Asterisk-määritykset, asentaa sitten uuden version ja testaa, että kaikki toimii. Jos jokin epäonnistuu, palataan automaattisesti edelliseen versioon. Asterisk käynnistetään päivityksen aikana uudelleen: käynnissä olevat puhelut katkeavat, joten päivitystä ei aloiteta puhelujen ollessa käynnissä. Päivityksen voi ajaa myös palvelimella: <code>sudo aipbx-update</code>',
