    'certificates.mode_custom' => 'Ladattu varmenne',
    'certificates.mode_selfsigned' => 'Itse allekirjoitettu',
    'certificates.mode_unknown' => 'Tuntematon lähde',
    'certificates.issue_missing' => 'Aktiivista varmennetta ei löytynyt.',
