    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: ota käyttöön "Cloud Text-to-Speech API"; käytä palvelutilin JSON-avainta (IAM → Service Accounts → Keys → JSON) tai API-avainta. Enintään %s merkkiä pyyntöä kohden; pidemmät tekstit jaetaan osiin.',
    'ai_tts.provider_hint_polly' => 'Luo AWS IAM:ssä käyttöavain käyttäjälle, jolla on vain oikeudet "polly:SynthesizeSpeech" ja "polly:DescribeVoices". Enintään %s merkkiä pyyntöä kohden.',
    'ai_tts.provider_hint_azure' => 'Luo Azure-portaalissa "Speech"-resurssi; avain ja alue (esim. westeurope) löytyvät sen "Keys and Endpoint" -sivulta. Enintään %s merkkiä pyyntöä kohden.',
    'ai_tts.provider_hint_elevenlabs' => 'ElevenLabs → Profile → API Keys. Äänet tulevat tilisi äänikirjastosta ja ovat monikielisiä. Enintään %s merkkiä pyyntöä kohden.',
